/**
 * 库容调洪判定：以“设计洪水量”对比“当前水位可用调洪库容”。
 */
public enum CapacityJudgment {
    /** 设计洪水量小于可用库容：安全。 */
    SAFE,
    /** 设计洪水量恰等于可用库容：临界。 */
    CRITICAL,
    /** 设计洪水量大于可用库容：须泄流。 */
    RELEASE_REQUIRED
}

package com.example.starter.flood.domain;

/**
 * 单项监测指标判定（干滩长度、浸润线埋深），低于安全下限判险、恰等下限判临界。
 */
public enum IndicatorJudgment {
    /** 高于安全下限。 */
    SAFE,
    /** 恰等于安全下限：临界。 */
    CRITICAL,
    /** 低于安全下限：险。 */
    DANGER
}

package com.example.starter.flood.domain;

/**
 * 调洪演算综合判定：库容与干滩长度、浸润线埋深合并口径。
 * 任一单项判“险”即 DANGER；无险但有临界即 CRITICAL；全部安全且库容安全才 SAFE。
 */
public enum DangerJudgment {
    SAFE,
    CRITICAL,
    DANGER
}

package com.example.starter.flood.domain;

/**
 * 处置链与方案生命周期状态。
 */
public enum ChainStatus {
    /** 处置链生效中，可继续演算/下达指令；方案执行中。 */
    ACTIVE,
    /** 方案已回执完成（不再执行中）。 */
    COMPLETED,
    /** 终态：已复盘归档，重复归档幂等返回；迟到读数只记事件。 */
    ARCHIVED
}

package com.example.starter.flood.domain;

/**
 * 泄流指令链状态：下达→签收→执行→回执；超时未签收进入升级态。
 */
public enum OrderStatus {
    /** 已下达，等待签收。 */
    ISSUED,
    /** 已签收。 */
    SIGNED,
    /** 已执行（现场开闸），等待回执。 */
    EXECUTING,
    /** 已回执，指令链闭环。 */
    RECEIPTED,
    /** 恰满签收时限未签收，自动升级值班领导。 */
    ESCALATED
}

