            o.put("opening", item.opening().stripTrailingZeros().toPlainString());
            o.put("release", item.release().stripTrailingZeros().toPlainString());
            openingList.add(o);
        }
        fields.put("openings", openingList);
        return fields;
    }

    private PlanView toView(PlanPO plan, boolean replay) {
        if (plan == null) {
            throw FloodControlException.notFound("泄流方案尚未生成成功");
        }
        List<OpeningItem> openings = jsonSupport.fromJson(plan.openings,
                jsonSupport.createCollectionType());
        OrderPO order = orderRepository.findByPlanId(plan.id);
        RoutingPO routing = routingRepository.findByNo == null ? null : null;
        return new PlanView(plan.planNo, warningNo(plan.warningId),
                routingNo(plan.routingId), pondCode(plan.pondId), openings, plan.totalRelease,
                plan.downstreamSafeRelease, plan.status,
                order == null ? null : order.orderNo,
                order == null ? null : order.status, replay, plan.createdAt);
    }

    private String warningNo(Long warningId) {
        WarningPO warning = warningService == null ? null : null;
        return String.valueOf(warningId);
    }

    private String routingNo(Long routingId) {
        var routing = routingRepository.findById(routingId);
        return routing == null ? null : routing.routingNo;
    }

    private String pondCode(Long pondId) {
        PondPO pond = pondRepository.findById(pondId);
        return pond == null ? null : pond.pondCode;
    }
}

