/**
 * 判迟到：库内存在已归档处置链，且读数采样时刻不晚于归档时刻（复盘窗口内的数据视为迟到）。
 */
private boolean isLateAfterArchive(Long pondId, LocalDateTime sampleTime) {
    List<WarningPO> archived = warningRepository.findArchivedByPond(pondId);
    return archived.stream().anyMatch(w -> !sampleTime.isAfter(w.archivedAt));
}

