/**
 * 判迟到：该库已无生效处置链但存在已归档链，即读数在复盘归档之后才送达。
 * 仍有生效链时读数正常入库，归档判定不依据采样时刻（乱序读数应按时刻归位而非丢弃）。
 */
private boolean isLateAfterArchive(Long pondId, LocalDateTime sampleTime) {
